cd {{REPO}}/graphos-demo/lumen_books && python3 - <<'E'
import json,glob
req={'Book':['id','title','authorId','priceCents','currency'],'Order':['id','customerId','status','items','totalCents'],'OrderItem':['bookId','quantity']}
props={'Book':'id title authorId isbn priceCents currency genres publishedAt stock metadata'.split(),'Order':'id customerId status items totalCents payment createdAt'.split(),'OrderItem':['bookId','quantity','unitPriceCents']}
def chk(n,o,where):
    for k in req[n]:
        if o.get(k) is None: print('NULL/missing required',n,k,where)
    for k,v in o.items():
        if k not in props[n]: print('undocumented',n,k,where)
        if v is None and k not in req[n]: print('null optional',n,k,where)
    if n=='Order':
        for i in o.get('items') or []: chk('OrderItem',i,where)
        p=o.get('payment')
        if p and p.get('type') not in('card','bank'): print('payment type',p)
        if p: print('  pay',where,o['id'],sorted(p))
for f in glob.glob('.factory/samples/get_books*/*.json')+glob.glob('.factory/samples/get_orders*/*.json'):
    r=json.load(open(f))['response']
    if r['status']!=200: continue
    b=r['body']; items=b['data'] if 'data' in b else [b]
    for o in items: chk('Book' if 'books' in f else 'Order',o,f.split('samples/')[1])
    print(f.split('samples/')[1],{k:v for k,v in b.items() if k!='data'} if 'data' in b else '', 'enums', {o.get('currency') or o.get('status') for o in items})
E

